corrected_code:
const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { db } = require('../db');
const s3 = new S3Client({ region: 'eu-central-1' });

exports.handler = async (event) => {
  const dashboardId = event.pathParameters?.dashboardId;
  const callerAccountId = event.requestContext?.authorizer?.accountId;

  const record = await db.query(
    'SELECT id FROM dashboards WHERE id = $1 AND account_id = $2',
    [dashboardId, callerAccountId]
  );
  if (!record.rows.length) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Access denied to requested dashboard snapshot' }) };
  }

  const data = await s3.send(new GetObjectCommand({
    Bucket: 'cloud-monitoring-dashboards',
    Key: `snapshots/${dashboardId}.json`
  }));
  const content = await data.Body.transformToString();

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: content
  };
};
